static void executeAndPrint(Statement s, String sql) throws SQLException {
  boolean hasResultSet = s.execute(sql);
  if (hasResultSet) {
    try (ResultSet rs = s.getResultSet()) { while (rs.next()) System.out.println(rs.getObject(1)); }
  } else {
    System.out.println("Update count: " + s.getUpdateCount());
  }
}

