static void runSql(Statement s, String sql) throws SQLException {
  boolean hasRs = s.execute(sql);
  if (hasRs) {
    int count = 0;
    try (ResultSet rs = s.getResultSet()) { while (rs.next()) count++; }
    System.out.println("Wierszy: " + count);
  } else {
    System.out.println("Zmienionych: " + s.getUpdateCount());
  }
}

