static int countRows(Statement s, String tableName) throws SQLException {
  try (ResultSet rs = s.executeQuery("SELECT COUNT(*) FROM " + tableName)) { rs.next(); return rs.getInt(1); }
}

static void printRows(Statement s, String sql, String... columnNames) throws SQLException {
  try (ResultSet rs = s.executeQuery(sql)) {
    while (rs.next()) {
      StringBuilder sb = new StringBuilder();
      for (String col : columnNames) sb.append(rs.getObject(col)).append(" ");
      System.out.println(sb);
    }
  }
}

static void runScript(Statement s, String[] commands) throws SQLException {
  int resultSets = 0, updates = 0;
  for (String cmd : commands) { if (s.execute(cmd)) resultSets++; else updates++; }
  System.out.println("ResultSety: " + resultSets + ", update/DDL: " + updates);
}

